import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../../features/common/presentation/feature_screen.dart';
final routerProvider = Provider<GoRouter>((ref) => GoRouter(initialLocation: '/splash', routes: [GoRoute(path: '/splash', builder: (_, __) => const FeatureScreen(title: 'VJtronix', message: 'Preparing your experience')), GoRoute(path: '/login', builder: (_, __) => const FeatureScreen(title: 'Login', message: 'Sign in to continue')), GoRoute(path: '/register', builder: (_, __) => const FeatureScreen(title: 'Register', message: 'Create your account')), GoRoute(path: '/forgot-password', builder: (_, __) => const FeatureScreen(title: 'Forgot Password', message: 'Recover your account')), GoRoute(path: '/reset-password', builder: (_, __) => const FeatureScreen(title: 'Reset Password', message: 'Choose a secure password')), GoRoute(path: '/blog/:slug', builder: (_, s) => FeatureScreen(title: 'Blog Details', message: s.pathParameters['slug'] ?? 'Article')), GoRoute(path: '/projects/:slug', builder: (_, s) => FeatureScreen(title: 'Project Details', message: s.pathParameters['slug'] ?? 'Project')), GoRoute(path: '/shop/:slug', builder: (_, s) => FeatureScreen(title: 'Product Details', message: s.pathParameters['slug'] ?? 'Product')), GoRoute(path: '/cart', builder: (_, __) => const FeatureScreen(title: 'Cart', message: 'Your selected products')), GoRoute(path: '/wishlist', builder: (_, __) => const FeatureScreen(title: 'Wishlist', message: 'Saved products')), GoRoute(path: '/notifications', builder: (_, __) => const FeatureScreen(title: 'Notifications', message: 'You are all caught up')), GoRoute(path: '/settings', builder: (_, __) => const FeatureScreen(title: 'Settings', message: 'Appearance and preferences')), StatefulShellRoute.indexedStack(builder: (_, __, shell) => AppScaffold(shell: shell), branches: [for (final item in const [('home', 'Home', 'Featured blogs, projects and products'), ('blog', 'Blog', 'Explore articles and categories'), ('shop', 'Shop', 'Browse VJtronix products'), ('ai', 'AI Chat', 'Ask VJtronix'), ('profile', 'Profile', 'Account, orders and bookmarks')]) StatefulShellBranch(routes: [GoRoute(path: '/${item.$1}', builder: (_, __) => FeatureScreen(title: item.$2, message: item.$3))])]) ]));
class AppScaffold extends StatelessWidget { const AppScaffold({required this.shell, super.key}); final StatefulNavigationShell shell; @override Widget build(BuildContext context) => Scaffold(body: shell, bottomNavigationBar: NavigationBar(selectedIndex: shell.currentIndex, onDestinationSelected: shell.goBranch, destinations: const [NavigationDestination(icon: Icon(Icons.home_outlined), label: 'Home'), NavigationDestination(icon: Icon(Icons.article_outlined), label: 'Blog'), NavigationDestination(icon: Icon(Icons.storefront_outlined), label: 'Shop'), NavigationDestination(icon: Icon(Icons.smart_toy_outlined), label: 'AI'), NavigationDestination(icon: Icon(Icons.person_outline), label: 'Profile')])); }
